package edu.smartstudy.progress;
import edu.smartstudy.focus.*;import edu.smartstudy.planning.*;import edu.smartstudy.quiz.*;import edu.smartstudy.user.UserRepository;import java.time.*;import java.util.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/progress")public class ProgressController{private final UserRepository users;private final StudyTaskRepository tasks;private final FocusSessionRepository focus;private final QuizAttemptRepository attempts;public ProgressController(UserRepository users,StudyTaskRepository tasks,FocusSessionRepository focus,QuizAttemptRepository attempts){this.users=users;this.tasks=tasks;this.focus=focus;this.attempts=attempts;}@GetMapping("/overview")public Map<String,Object> overview(Authentication auth){Long id=users.findByEmailIgnoreCase(auth.getName()).orElseThrow().getId();long totalTasks=tasks.countByStudentId(id),done=tasks.countByStudentIdAndStatus(id,"COMPLETED");List<QuizAttempt> history=attempts.findTop100ByStudentIdOrderBySubmittedAtDesc(id);int scored=history.stream().mapToInt(QuizAttempt::getScore).sum(),questions=history.stream().mapToInt(QuizAttempt::getTotalQuestions).sum();return Map.of("totalStudyMinutes",focus.totalSeconds(id)/60,"completedTasks",done,"totalTasks",totalTasks,"taskCompletionPercent",totalTasks==0?0:Math.round(100.0*done/totalTasks),"quizAttempts",history.size(),"quizAccuracyPercent",questions==0?0:Math.round(100.0*scored/questions));}@GetMapping("/trends")public Map<String,Object> trends(Authentication auth){Long id=users.findByEmailIgnoreCase(auth.getName()).orElseThrow().getId();LocalDate today=LocalDate.now();Instant from=today.minusDays(6).atStartOfDay(ZoneId.systemDefault()).toInstant();Map<LocalDate,Long> minutes=new TreeMap<>();for(int i=0;i<7;i++)minutes.put(today.minusDays(6-i),0L);for(FocusSession s:focus.findByStudentIdAndStartedAtGreaterThanEqualOrderByStartedAtAsc(id,from)){if(s.getStartedAt()!=null){LocalDate day=s.getStartedAt().atZone(ZoneId.systemDefault()).toLocalDate();minutes.computeIfPresent(day,(k,v)->v+s.getDurationSeconds()/60);}}Map<LocalDate,Long> completions=new TreeMap<>();Map<LocalDate,Long> quizScores=new TreeMap<>();Map<LocalDate,Long> quizTotals=new TreeMap<>();for(int i=0;i<7;i++){LocalDate date=today.minusDays(6-i);completions.put(date,0L);quizScores.put(date,0L);quizTotals.put(date,0L);}for(StudyTask task:tasks.findTop100ByStudentIdOrderByScheduledDateAscCreatedAtDesc(id)){if(task.getCompletedAt()!=null){LocalDate day=task.getCompletedAt().atZone(ZoneId.systemDefault()).toLocalDate();completions.computeIfPresent(day,(k,v)->v+1);}}for(QuizAttempt attempt:attempts.findTop100ByStudentIdOrderBySubmittedAtDesc(id)){if(attempt.getSubmittedAt()!=null){LocalDate day=attempt.getSubmittedAt().atZone(ZoneId.systemDefault()).toLocalDate();quizScores.computeIfPresent(day,(k,v)->v+attempt.getScore());quizTotals.computeIfPresent(day,(k,v)->v+attempt.getTotalQuestions());}}List<Map<String,Object>> quizAccuracy=new ArrayList<>();for(LocalDate date:quizTotals.keySet()){long total=quizTotals.get(date),score=quizScores.get(date);quizAccuracy.add(Map.of("date",date.toString(),"percent",total==0?0:Math.round(100.0*score/total)));}return Map.of("studyMinutes",minutes.entrySet().stream().map(e->Map.of("date",e.getKey().toString(),"minutes",e.getValue())).toList(),"taskCompletions",completions.entrySet().stream().map(e->Map.of("date",e.getKey().toString(),"completed",e.getValue())).toList(),"quizAccuracy",quizAccuracy);}}
